SELECT * FROM media_asset
WHERE deleted_at IS NULL
AND type = #{type}
AND status = #{status}
AND uploaded_by = #{uploadedBy}

    AND tags @> #{tags,typeHandler=kr.co.ircp.cms.domain.media.mapper.StringArrayTypeHandler}

AND created_at >= #{from}
AND created_at <= #{to}
ORDER BY created_at DESC
LIMIT #{size} OFFSET #{page} * #{size}

